CREATE TABLE "dim_product_id" ("product_id" VARCHAR, "product_name" VARCHAR, "category" VARCHAR, "brand" VARCHAR, "unit_price" VARCHAR, PRIMARY KEY ("product_id"));
CREATE TABLE "dim_warehouse_id" ("warehouse_id" VARCHAR, "warehouse_name" VARCHAR, "warehouse_city" VARCHAR, "warehouse_postcode" VARCHAR, PRIMARY KEY ("warehouse_id"));
CREATE TABLE "dim_customer_id" ("customer_id" VARCHAR, "customer_name" VARCHAR, "customer_city" VARCHAR, "customer_segment" VARCHAR, PRIMARY KEY ("customer_id"));
CREATE TABLE "dim_order_id" ("order_id" VARCHAR, "order_date" VARCHAR, "order_status" VARCHAR, "sales_channel" VARCHAR, PRIMARY KEY ("order_id"));
CREATE TABLE "dim_product_id_warehouse_id" ("product_id" VARCHAR, "warehouse_id" VARCHAR, "bin_location" VARCHAR, "reorder_point" INTEGER, PRIMARY KEY ("product_id", "warehouse_id"));
CREATE TABLE "records" ("order_id" VARCHAR, "customer_id" VARCHAR, "line_number" INTEGER, "product_id" VARCHAR, "warehouse_id" VARCHAR, "quantity" INTEGER, "discount_percent" INTEGER, "delivery_note" VARCHAR, PRIMARY KEY ("order_id", "line_number"), FOREIGN KEY ("product_id") REFERENCES "dim_product_id" ("product_id"), FOREIGN KEY ("warehouse_id") REFERENCES "dim_warehouse_id" ("warehouse_id"), FOREIGN KEY ("customer_id") REFERENCES "dim_customer_id" ("customer_id"), FOREIGN KEY ("order_id") REFERENCES "dim_order_id" ("order_id"), FOREIGN KEY ("product_id", "warehouse_id") REFERENCES "dim_product_id_warehouse_id" ("product_id", "warehouse_id"));
CREATE VIEW dataset AS SELECT r."order_id" AS "order_id", d4."order_date" AS "order_date", d4."order_status" AS "order_status", d4."sales_channel" AS "sales_channel", r."customer_id" AS "customer_id", d3."customer_name" AS "customer_name", d3."customer_city" AS "customer_city", d3."customer_segment" AS "customer_segment", r."line_number" AS "line_number", r."product_id" AS "product_id", d1."product_name" AS "product_name", d1."category" AS "category", d1."brand" AS "brand", d1."unit_price" AS "unit_price", r."warehouse_id" AS "warehouse_id", d2."warehouse_name" AS "warehouse_name", d2."warehouse_city" AS "warehouse_city", d2."warehouse_postcode" AS "warehouse_postcode", d5."bin_location" AS "bin_location", d5."reorder_point" AS "reorder_point", r."quantity" AS "quantity", r."discount_percent" AS "discount_percent", r."delivery_note" AS "delivery_note" FROM records AS r JOIN "dim_product_id" AS d1 ON r."product_id" = d1."product_id" JOIN "dim_warehouse_id" AS d2 ON r."warehouse_id" = d2."warehouse_id" JOIN "dim_customer_id" AS d3 ON r."customer_id" = d3."customer_id" JOIN "dim_order_id" AS d4 ON r."order_id" = d4."order_id" JOIN "dim_product_id_warehouse_id" AS d5 ON r."product_id" = d5."product_id" AND r."warehouse_id" = d5."warehouse_id";
